echo "== no content-type ==";
printf "hello-no-ct" | curl -s -w "\nHTTP:%{http_code}\n" -X PUT --data-binary @- http://server:8080/blobs/a.txt;
echo "== octet-stream ==";
printf "hello-octet" | curl -s -w "\nHTTP:%{http_code}\n" -X PUT -H "Content-Type: application/octet-stream" --data-binary @- http://server:8080/blobs/b.txt;
echo "== form-urlencoded (edge case) ==";
printf "hello-form" | curl -s -w "\nHTTP:%{http_code}\n" -X PUT -H "Content-Type: application/x-www-form-urlencoded" --data-binary @- http://server:8080/blobs/c.txt;
echo "== GET a.txt ==";
curl -s -w "\nHTTP:%{http_code}\n" http://server:8080/blobs/a.txt;
echo "== GET b.txt ==";
curl -s -w "\nHTTP:%{http_code}\n" http://server:8080/blobs/b.txt;
echo "== GET c.txt ==";
curl -s -w "\nHTTP:%{http_code}\n" http://server:8080/blobs/c.txt;
'

rm -rf /tmp/syncbox-data && mkdir -p /tmp/syncbox-data
docker compose restart server 2>&1 | tail -5
sleep 1
docker run --rm --network workspace_default curlimages/curl:latest sh -c '
echo "== no content-type, plain text ==";
printf "hello-no-ct" | curl -s -w "\nHTTP:%{http_code}\n" -X PUT --data-binary @- http://server:8080/blobs/a.txt;
echo "== no content-type, arbitrary binary bytes 0..255 ==";
python3 -c "import sys; sys.stdout.buffer.write(bytes(range(256)))" 2>/dev/null > /tmp/bin.dat || perl -e "print pack(\"C*\", 0..255)" > /tmp/bin.dat;
curl -s -w "\nHTTP:%{http_code}\n" -X PUT --data-binary @/tmp/bin.dat http://server:8080/blobs/binary.bin;
echo "== octet-stream nested key ==";
printf "nested content" | curl -s -w "\nHTTP:%{http_code}\n" -X PUT -H "Content-Type: application/octet-stream" --data-binary @- http://server:8080/blobs/docs/readme.txt;
echo "== GET a.txt ==";
curl -s -w "\nHTTP:%{http_code}\n" http://server:8080/blobs/a.txt;
echo "== GET binary.bin size check ==";
curl -s http://server:8080/blobs/binary.bin | wc -c;
echo "== GET docs/readme.txt ==";
curl -s -w "\nHTTP:%{http_code}\n" http://server:8080/blobs/docs/readme.txt;
